#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# Merge gate: every commit in the range must pass the commit-msg rules and be signed.
# Executors could skip the hook (--no-verify) or signing (--no-gpg-sign); this catches it
# before the architect merges. Usage: scripts/orca/check-commits.sh main..task/NNN-slug
set -euo pipefail
range=${1:?usage: scripts/orca/check-commits.sh <range>}
hook="$(git rev-parse --show-toplevel)/.githooks/commit-msg"
tmp=$(mktemp "${TMPDIR:-/tmp}/check-commits.XXXX")
trap 'rm -f "$tmp"' EXIT
fails=0
for c in $(git rev-list --no-merges "$range"); do
  if ! git cat-file -p "$c" | grep -q '^gpgsig '; then
    echo "check-commits: $c is not signed" >&2
    fails=$((fails + 1))
  fi
  git log -1 --format=%B "$c" > "$tmp"
  if ! "$hook" "$tmp" 2>/dev/null; then
    echo "check-commits: $c message breaks the commit-msg rules" >&2
    fails=$((fails + 1))
  fi
done
[ "$fails" -eq 0 ] && echo "check-commits: $range ok"
[ "$fails" -eq 0 ]
